        idl_st = idl_rep_status_var(idl_b1, idl_got[0], sizeof(*idl_r));
    const void *idl_p0 = NULL;
    uint32_t idl_l0 = 0;
    if (idl_st == OK && !idl_get(idl_b1, idl_got[0], &idl_o, 4, 4, &idl_p0, &idl_l0))
        idl_st = ERR_INTERNAL;
